/* Shared connection commands with explicit floor ownership and camera pick tolerance. */
(function(){'use strict';let pending=null,scale=null;
const basePixels=worldPixels;worldPixels=function(px){return scale!==null?px*scale:basePixels(px);};
function inFloor(hit,fn){if(!model.floors[hit.floor])return{valid:false,reason:'Choose an existing floor'};const old=floorId,oldScale=scale;floorId=hit.floor;scale=hit.worldPerPixel||.03;try{return fn();}finally{floorId=old;scale=oldScale;}}
function scope(){return currentBuilding().id;}
function preview(mode,hit,start){if(!hit)return{valid:false,reason:'Point at a wall or room'};return inFloor(hit,()=>{let q;const source=mode==='door'?null:start||pending;if(source&&source.scope!==scope())pending=null;if(source&&source.floor!==hit.floor)return{valid:false,reason:'Doors connect rooms on the same floor; use stairs between floors'};if(mode==='door')q=doorPlacementCandidate(hit.p);else if(mode==='disconnect'){const nearest=connection(hit.door)||nearestDoor(hit.p,14),ids=source?.room&&hit.room&&source.room!==hit.room?linkedConnections(source.room,hit.room).map(d=>d.id):nearest?[nearest.id]:[];q={valid:!!ids.length,ids,geometry:ids.length?doorGeometry(connection(ids[0])):null,reason:ids.length?'Click to remove connection':'Click a connection, or drag between connected rooms'};}else if(source?.room){q=gestureCandidate(room(source.room),hit.room&&hit.room!==source.room?room(hit.room):null,hit.p,source.p);}else q={valid:false,reason:'Click a source room, then another room; or drag between them'};const host=room(q.door?.a||source?.room||hit.room);return{...q,fid:hit.floor,z:host?.z??floor().z,scope:scope()};});}
function begin(mode,hit){if(!hit)return null;return{mode,hit:{...hit,scope:scope()},scope:scope(),pending:pending?{...pending}:null};}
function finish(g,hit,moved){if(!g||g.scope!==scope()||!hit)return false;const source=moved?g.hit:g.pending;if(g.mode==='connect'&&!moved&&!source){if(!g.hit.room){notify('Choose a source room first');return false;}pending=g.hit;notify('Choose another room or click outside to connect');return true;}if(g.mode==='disconnect'&&!moved&&!source){const q=preview(g.mode,hit);if(!q.valid&&g.hit.room){pending=g.hit;notify('Choose the connected room to disconnect');return true;}}
const q=preview(g.mode,hit,source);pending=null;if(!q.valid){notify(q.reason);return false;}floorId=hit.floor;return g.mode==='disconnect'?removeConnections(q.ids):addCandidate(q);}
window.KERN_CONNECTION_3D={preview,begin,finish,cancel(){pending=null;},get pending(){return pending;}};
})();
